var i=`microservices-architecture`;var r=15;var s={en:[{id:`T015-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Microservices Architecture`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Layered Architecture divides an application into presentation, business/application logic, and data access responsibilities.`},{id:`B`,text:`A modular monolith deploys as one application but enforces domain module boundaries internally.`},{id:`C`,text:`Event-Driven Architecture communicates facts about state changes through events.`},{id:`D`,text:`Microservices split a system into independently deployable services around bounded business capabilities.`}]},{id:`T015-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Microservices Architecture`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Each service owns its data and API, deploys on its own cadence, and tolerates remote failures.`},{id:`B`,text:`Commands validate against current state, then append immutable events using concurrency control.`},{id:`C`,text:`Maintain clear write invariants while shaping read models for actual query needs.`},{id:`D`,text:`Distinguish entities/domain rules, application use cases, interface adapters, and external infrastructure.`}]},{id:`T015-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A marketplace may separate catalog, orders, and fulfillment after those teams need independent release cycles.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Consistent error mapping prevents database exceptions from leaking into user-visible responses.`},{id:`B`,text:`Payment implementation changes without rewriting housekeeping; a single transaction remains possible where appropriate.`},{id:`C`,text:`Express controllers translate HTTP input, while MongoDB adapters implement storage details.`},{id:`D`,text:`Order placement then requires event delivery contracts and careful handling of fulfillment failures.`}]},{id:`T015-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Microservices Architecture`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Do not split solely by database tables or developer teams.`},{id:`B`,text:`Separate read databases add synchronization lag, deployment work and reconciliation paths.`},{id:`C`,text:`Events introduce eventual consistency, duplicate delivery, schema evolution and debugging challenges.`},{id:`D`,text:`A strict three-tier pattern can become a pass-through call chain where every layer adds no value.`}]},{id:`T015-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`They trade local modularity and deployment independence for distributed-systems complexity.`}]}]},{id:`T015-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A small team must start with microservices to be ready for future scale.`}]}]},{id:`T015-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Distributed transactions, network latency, multiple pipelines, and operational burden can make microservices worse than a modular monolith for an MVP.`}]}]},{id:`T015-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Microservices Architecture`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A modular monolith permits all modules to update each other's private tables.`},{id:`B`,text:`Microservices remove the need for tracing, retry policy and distributed data ownership.`},{id:`C`,text:`Each service owns its data and API, deploys on its own cadence, and tolerates remote failures.`},{id:`D`,text:`Microservices split a system into independently deployable services around bounded business capabilities.`}]},{id:`T015-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Microservices Architecture`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A small team must start with microservices to be ready for future scale.`},{id:`B`,text:`Distributed transactions, network latency, multiple pipelines, and operational burden can make microservices worse than a modular monolith for an MVP.`},{id:`C`,text:`An event store can freely edit historical events without affecting projections.`},{id:`D`,text:`Order placement then requires event delivery contracts and careful handling of fulfillment failures.`}]},{id:`T015-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A marketplace may separate catalog, orders, and fulfillment after those teams need independent release cycles.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to propose monolith and microservice designs for an order platform. Require deployment diagrams, data ownership, failure cases, operational costs, and a migration trigger.`},{id:`B`,text:`Review a layered service for controller business logic, leaking ORM types, and untested error mapping. Ask the agent for a minimal refactor and trace one request through all layers.`},{id:`C`,text:`Design a booking-confirmed event and two independent consumers. Ask the agent to demonstrate duplicate delivery, consumer retry, schema versioning and an outbox failure case.`},{id:`D`,text:`Ask an agent to separate booking commands from reporting queries inside a modular monolith first. Define authorization on both paths and note when a separate projection would pay off.`}]},{id:`T015-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What business or team evidence justifies paying the distributed-systems tax?`}]}]},{id:`T015-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A marketplace may separate catalog, orders, and fulfillment after those teams need independent release cycles.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Microservices Architecture`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T015-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A marketplace may separate catalog, orders, and fulfillment after those teams need independent release cycles.`,b:!0},{t:` — propose three checks for `},{t:`Microservices Architecture`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T015-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A marketplace may separate catalog, orders, and fulfillment after those teams need independent release cycles.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T015-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Microservices Architecture`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A marketplace may separate catalog, orders, and fulfillment after those teams need independent release cycles.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T015-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Мікросервісна архітектура`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Шарова архітектура ділить застосунок на представлення, бізнес-логіку та доступ до даних.`},{id:`B`,text:`Модульний моноліт розгортається як один застосунок, але має внутрішні межі доменних модулів.`},{id:`C`,text:`Подієво-орієнтована архітектура передає факти про зміни стану через події.`},{id:`D`,text:`Мікросервіси ділять систему на незалежно розгортані сервіси навколо обмежених бізнес-можливостей.`}]},{id:`T015-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Мікросервісна архітектура`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Кожен сервіс володіє своїми даними й API та розгортається незалежно, враховуючи мережеві відмови.`},{id:`B`,text:`Команди перевіряють стан і додають незмінні події з контролем конкурентного запису.`},{id:`C`,text:`Зберігайте інваріанти на стороні запису, а моделі читання підлаштовуйте під запити.`},{id:`D`,text:`Розрізняйте сутності й доменні правила, сценарії застосунку, адаптери інтерфейсів і зовнішню інфраструктуру.`}]},{id:`T015-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Маркетплейс може відділити каталог, замовлення та виконання, коли командам потрібні незалежні релізи.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Узгоджений мапінг помилок не дозволяє виняткам БД потрапляти у відповіді користувачу.`},{id:`B`,text:`Зміни платежів не переписують прибирання; одна транзакція БД можлива там, де це доречно.`},{id:`C`,text:`Express-контролери перетворюють HTTP-вхід, а MongoDB-адаптери відповідають за збереження.`},{id:`D`,text:`Оформлення замовлення тоді вимагає контрактів подій і обробки збоїв виконання.`}]},{id:`T015-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Мікросервісна архітектура`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Не діліть систему лише за таблицями БД чи командами.`},{id:`B`,text:`Окрема БД читання додає затримку синхронізації, роботу з розгортанням і звіркою.`},{id:`C`,text:`Події додають eventual consistency, дублікати доставки, еволюцію схем і складніший дебаг.`},{id:`D`,text:`Сувора тришарова структура іноді перетворюється на ланцюжок порожніх викликів.`}]},{id:`T015-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Вони обмінюють незалежність розгортання на складність розподілених систем.`}]}]},{id:`T015-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Невелика команда мусить починати з мікросервісів, щоб бути готовою до масштабування.`}]}]},{id:`T015-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Розподілені транзакції, затримки, окремі CI/CD і експлуатаційні витрати можуть зробити мікросервіси гіршими за модульний моноліт для MVP.`}]}]},{id:`T015-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Мікросервісна архітектура`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Модульний моноліт дозволяє всім модулям змінювати приватні таблиці інших модулів.`},{id:`B`,text:`Мікросервіси усувають потребу в трасуванні, повторах і володінні даними.`},{id:`C`,text:`Кожен сервіс володіє своїми даними й API та розгортається незалежно, враховуючи мережеві відмови.`},{id:`D`,text:`Мікросервіси ділять систему на незалежно розгортані сервіси навколо обмежених бізнес-можливостей.`}]},{id:`T015-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Мікросервісна архітектура`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Невелика команда мусить починати з мікросервісів, щоб бути готовою до масштабування.`},{id:`B`,text:`Розподілені транзакції, затримки, окремі CI/CD і експлуатаційні витрати можуть зробити мікросервіси гіршими за модульний моноліт для MVP.`},{id:`C`,text:`Сховище подій може довільно переписувати історичні події без впливу на проєкції.`},{id:`D`,text:`Оформлення замовлення тоді вимагає контрактів подій і обробки збоїв виконання.`}]},{id:`T015-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Маркетплейс може відділити каталог, замовлення та виконання, коли командам потрібні незалежні релізи.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента порівняти моноліт і мікросервіси для замовлень. Вимагайте схеми розгортання, володіння даними, відмови, експлуатаційні витрати й критерії міграції.`},{id:`B`,text:`Перевірте шаровий сервіс на бізнес-логіку в контролері, витік ORM-типів і неперевірений мапінг помилок. Попросіть мінімальний рефакторинг і трасування запиту через шари.`},{id:`C`,text:`Спроєктуйте подію підтвердження бронювання й двох незалежних споживачів. Попросіть показати дубльовану доставку, повтори, версії схеми та збій outbox.`},{id:`D`,text:`Попросіть агента відділити команди бронювання від звітних запитів спершу в модульному моноліті. Визначте авторизацію для обох шляхів і умови появи окремої проєкції.`}]},{id:`T015-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які бізнесові або командні факти виправдовують витрати на розподілену систему?`}]}]},{id:`T015-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Маркетплейс може відділити каталог, замовлення та виконання, коли командам потрібні незалежні релізи.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Мікросервісна архітектура`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T015-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Маркетплейс може відділити каталог, замовлення та виконання, коли командам потрібні незалежні релізи.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Мікросервісна архітектура`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T015-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Маркетплейс може відділити каталог, замовлення та виконання, коли командам потрібні незалежні релізи.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T015-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Мікросервісна архітектура`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Маркетплейс може відділити каталог, замовлення та виконання, коли командам потрібні незалежні релізи.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var a={slug:i,topicId:15,questions:s};export{a as default,s as questions,i as slug,r as topicId};